const modal=document.querySelector('#modal'),content=document.querySelector('#content');
let step=0,topics=[],role='Busco acompañamiento',alias='',format='Ambos',availability='Por la tarde';
const names=['Depresión','Pérdida de pareja','Duelo','Adicciones'];
function open(html){content.innerHTML=html;if(!modal.open)modal.showModal()}
function close(){modal.close();content.innerHTML='';topics=[];alias=''}
document.querySelector('.close').onclick=close;
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
modal.addEventListener('cancel',()=>{topics=[];alias=''});
function start(topic){topics=topic?[topic]:[];step=0;role='Busco acompañamiento';render()}
document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start());
document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>start(b.dataset.topic));
document.querySelector('#mentor').onclick=()=>{start();role='Quiero acompañar'};
function render(){
const head=`<p class="eyebrow">VAMOS A TU RITMO · ${step+1} DE 4</p><progress max="4" value="${step+1}"></progress>`;
if(step===0){open(head+`<h2>Empecemos por conocernos.</h2><p>Esta es una demostración: no crearemos una cuenta ni guardaremos tus respuestas. Usa un apodo ficticio.</p><form id="intro"><label>¿Cómo quieres que te llamemos?<input id="alias" maxlength="30" placeholder="Tu apodo" autocomplete="off" required></label><label>¿Cómo quieres participar?<select id="role"><option>Busco acompañamiento</option><option>Quiero acompañar</option><option>Ambas cosas</option></select></label><label><input type="checkbox" required> Tengo 18 años o más y entiendo que es apoyo entre pares.</label><button>Continuar ↗</button></form>`);document.querySelector('#alias').value=alias;document.querySelector('#role').value=role;document.querySelector('#intro').onsubmit=e=>{e.preventDefault();alias=document.querySelector('#alias').value.trim();if(!alias){document.querySelector('#alias').setCustomValidity('Escribe un apodo.');document.querySelector('#alias').reportValidity();return}role=document.querySelector('#role').value;step++;render()};}
if(step===1){open(head+`<h2>¿Qué te gustaría compartir?</h2><p>Puedes elegir varios temas u omitir esta pregunta. No es una evaluación clínica.</p>${names.map((n,i)=>`<button class="choice ${topics.includes(n)?'selected':''}" data-n="${i}" aria-pressed="${topics.includes(n)}">${n} ${topics.includes(n)?'✓':'+'}</button>`).join('')}<div class="actions"><button id="back">Atrás</button><button id="next">${topics.length?'Continuar':'Omitir por ahora'} ↗</button></div>`);content.querySelectorAll('[data-n]').forEach(b=>b.onclick=()=>{const n=names[Number(b.dataset.n)];topics=topics.includes(n)?topics.filter(t=>t!==n):[...topics,n];render()});bindNav();}
if(step===2){open(head+`<h2>¿Cómo te sentirías más a gusto?</h2><p>Estos detalles nos ayudan a sugerir conexiones compatibles.</p><label>¿Qué buscas?<select id="goal"><option>Que alguien me escuche</option><option>Compartir experiencias</option><option>Conocer una comunidad</option></select></label><label>Formato de acompañamiento<select id="format"><option>Ambos</option><option>Individual</option><option>Grupal</option></select></label><label>Disponibilidad<select id="time"><option>Por la tarde</option><option>Por la mañana</option><option>Por la noche</option><option>Horario flexible</option></select></label><div class="actions"><button id="back">Atrás</button><button id="next">Continuar ↗</button></div>`);document.querySelector('#format').value=format;document.querySelector('#time').value=availability;bindNav(()=>{format=document.querySelector('#format').value;availability=document.querySelector('#time').value});}
if(step===3){open(head+`<h2>Una conexión comienza con confianza.</h2><p>Escuchamos sin juzgar, respetamos los límites y no damos indicaciones de tratamiento. Puedes terminar una conexión o reportar una conducta en cualquier momento.</p><p class="notice">${role==='Busco acompañamiento'?'Antes de abrir un chat, ambas personas deben aceptar.':'Para acompañar se requerirá preparación y revisión por el equipo. Este prototipo no acredita acompañantes.'}</p><label><input type="checkbox" id="rules"> Entiendo los acuerdos de respeto y privacidad.</label><div class="actions"><button id="back">Atrás</button><button id="finish">Ver mi espacio ↗</button></div><p id="error" role="alert"></p>`);document.querySelector('#back').onclick=()=>{step--;render()};document.querySelector('#finish').onclick=()=>{if(!document.querySelector('#rules').checked){document.querySelector('#error').textContent='Acepta los acuerdos para continuar.';return}results()};}
}
function bindNav(save=()=>{}){document.querySelector('#back').onclick=()=>{step--;render()};document.querySelector('#next').onclick=()=>{save();step++;render()}}
function results(){open(`<p class="eyebrow">TU ESPACIO · DEMOSTRACIÓN</p><h2 id="greeting"></h2><p>Estas son sugerencias ilustrativas. Todos los perfiles y grupos son ficticios; no hay personas conectadas ni chat real.</p><div id="tags"></div><div class="profile"><span class="tag">PERSONA · PERFIL FICTICIO</span><h3>Alex · Escuchar y compartir</h3><p id="match"></p><button id="request">Explorar acompañamiento</button></div>${format!=='Individual'?'<div class="profile"><span class="tag">GRUPO · EJEMPLO</span><h3>Un día a la vez</h3><p>Un espacio de escucha para compartir experiencias. La moderación real está pendiente de implementación.</p><button id="group">Conocer el grupo</button></div>':''}<div class="actions"><button id="edit">Editar preferencias</button></div>`);document.querySelector('#greeting').textContent=`Aquí hay un lugar para ti, ${alias}.`;document.querySelector('#tags').textContent=(topics.length?topics.join(' · '):'Explorar sin tema definido')+' · '+availability;document.querySelector('#match').textContent=topics.length?`Ejemplo de afinidad por ${topics.join(', ').toLowerCase()} y disponibilidad ${availability.toLowerCase()}.`:'Selecciona un tema cuando quieras para obtener sugerencias más específicas.';document.querySelector('#request').onclick=()=>{open('<h2>Así comenzaría la conexión.</h2><p>En la aplicación real, revisarás la experiencia y preparación del acompañante, enviarás una solicitud y esperarás su aceptación. Todavía no se enviará ninguna solicitud.</p><button id="return">Volver a mi espacio</button>');document.querySelector('#return').onclick=results};const g=document.querySelector('#group');if(g)g.onclick=()=>{open('<h2>Un espacio para escucharnos.</h2><p>Los grupos tendrán acuerdos, horarios y moderadores. No compartas datos de contacto, información médica ni datos identificables en espacios públicos.</p><p class="notice">Este grupo es un ejemplo y no admite integrantes todavía.</p><button id="return">Volver</button>');document.querySelector('#return').onclick=results};document.querySelector('#edit').onclick=()=>{step=1;render()};}
document.querySelector('#login').onclick=()=>{open('<p class="eyebrow">ACCESO · PRÓXIMA ETAPA</p><h2>Bienvenido de nuevo.</h2><p>El acceso con correo, Apple y Google se conectará en la siguiente etapa. Esta versión permite recorrer la experiencia sin crear una cuenta ni introducir contraseñas.</p><button id="demo">Explorar la demostración ↗</button>');document.querySelector('#demo').onclick=()=>start()};
document.querySelector('#help').onclick=()=>open('<h2>Tu seguridad es lo primero.</h2><p>Este espacio no atiende emergencias. Si estás en peligro inmediato, contacta a los servicios de emergencia de tu localidad o acude a urgencias. Si puedes, busca a una persona de confianza que permanezca contigo.</p><p>Si necesitas apoyo por consumo de sustancias, busca atención profesional para planear los siguientes pasos de forma segura.</p>');
